        var body = await response.GetBodyAsync();
        if (body is null)
        {
            return 0;
        }

        var reader = await body.GetReaderAsync();
        long total = 0;
        while (true)
        {
            var chunk = await reader.ReadAsync();
            if (chunk.Done == true)
            {
